function string:trim()return self:match("^%s*(.-)%s*$")end;function noExt(a)a=a:gsub("%.+",".")if a:lower():match("%.luac$")then a=a:sub(1,-6)elseif a:lower():match("%.lua$")then a=a:sub(1,-5)end;return a end;local b=getWorkingDirectory().."/moduler"if not doesDirectoryExist(b)then createDirectory(b)end;function printErr(c)print("{ff7070}(error): {c0c0c0}"..c)end;function isScrLoaded(d)for e,f in pairs(script.list())do if noExt(f.name:lower():trim())==noExt(d:lower():trim())then return f end end;return false end;function extractSubmodule(g,h)g=g:gsub("\r\n","\n"):gsub("\r","\n")local i="%-%-%s*[Mm]oduler:%s*"..h.."%s*\n"local j,k=g:find("^"..i)if not j then j,k=g:find("\n"..i)end;if not j then return nil end;local l=k+1;local m=g:find("\n%-%-%s*[Mm]oduler:%s*[_%w]+%s*\n",l)local n=g:sub(l,m and m-1 or#g)n=n:gsub("^\n+",""):gsub("\n+$","")return n end;function findModulerCalls(o)local p={}local q={}local r=1;while true do local j=o:find("%-%-%[%[",r)if not j then break end;local m=o:find("%]%]",j+4)if m then table.insert(q,{s=j,e=m+1})r=m+2 else break end end;local function s(t)for u,v in ipairs(q)do if t>=v.s and t<=v.e then return true end end;return false end;for w,x in o:gmatch('(moduler%s*%(%s*["\']([^"\']+)["\']%s*%))')do local y=o:find(w,1,true)if y and not s(y)then local z=o:sub(1,y):match(".*\n()")or 1;local A=o:sub(z,y-1)if not A:match("^%s*%-%-")then local B=A:match('^([ \t]*)')table.insert(p,{module=x,indent=B or""})end end end;return p end;function applyIndentation(C,B)local D={}for E in(C.."\n"):gmatch("([^\r\n]*)\r?\n")do table.insert(D,E)end;if#D>0 then local F=nil;for u,E in ipairs(D)do if E:match("%S")then local G=E:match("^([ \t]*)")if not F or#G<#F then F=G end end end;if F and#F>0 then local H={}for u,E in ipairs(D)do if E:sub(1,#F)==F then table.insert(H,E:sub(#F+1))else table.insert(H,E)end end;D=H end end;if B==""then return table.concat(D,"\n")end;local I={}for u,E in ipairs(D)do table.insert(I,B..E)end;return table.concat(I,"\n")end;function build(d)d=noExt(d)local J=getWorkingDirectory()local b=J.."/moduler"local K=b.."/"..d;local L=J.."/"..d..".lua"if not doesFileExist(L)then printErr('Script "'..d..'.lua" not found')return false end;local M=io.open(L,"rb")if not M then printErr("Error opening script: "..d)return false end;local N=M:read("*a")M:close()if#N==0 then printErr(string.format('Script "%s" is empty.',d))return false end;local O=N:sub(1,4)if not O then printErr("No header found in script: "..d)return false end;if O=="\27Lua"or O=="\27LJ"then printErr(string.format('Script "%s" not supported as it is compiled. Use plain lua script.',d))return false end;local P=findModulerCalls(N)if#P==0 then print('No moduler() calls found in "'..d..'"')local Q,R=loadstring(N,d..".lua")if not Q then printErr("Syntax error in "..d..": "..R)return false end;local S,T=pcall(Q)if not S then printErr(string.format('Error executing script: "%s": %s',d,T))return false end;return true end;print('{44bbff}Moduler: {c0c0c0}Building "'..d..'" with '..#P..' module calls...')local U={}for u,V in ipairs(P)do local W,B=V.module,V.indent;local x=noExt(W)local h=nil;if x:match("%.",1,true)then local X={}for t in x:gmatch("[^%.]+")do table.insert(X,t)end;if#X>2 then printErr("Submodule nesting too deep: "..W)return false end;x=X[1]h=#X==2 and X[2]:trim()or nil;if h and(h:match("%[")or h:match("%]"))then printErr(string.format('Submodule "%s" in module "%s" in script "%s" has an invalid name.',h,x,d))return false end end;local Y=K.."/"..x..".lua"if not doesFileExist(Y)then printErr(string.format('Module "%s" not found for script "%s"',x,d))return false end;local Z=io.open(Y,"rb")if not Z then printErr(string.format('Error opening module "%s" for script "%s"',x,d))return false end;local g=Z:read("*a")Z:close()if#g==0 then printErr(string.format('Module "%s" for script "%s" is empty.',x,d))return false end;local _=g:sub(1,4)if not _ then printErr(string.format('No header found in module "%s" for script "%s"',x,d))return false end;if _=="\27Lua"or _=="\27LJ"then printErr(string.format('Module "%s" for script "%s" not supported as it is compiled. Use plain lua module.',x,d))return false end;local a0;if h then a0=extractSubmodule(g,h)if not a0 then printErr(string.format('Submodule "%s" not found in module "%s" for script "%s"',h,x,d))return false end else a0=g end;local a1,a2=loadstring(a0,"@"..x..(h and"."..h or""))if not a1 then printErr(string.format('Syntax error in "%s" for script "%s": %s',W,d,a2))return false end;local a3=applyIndentation(a0,B)table.insert(U,{marker='moduler%s*%(%s*["\']'..W:gsub("%.","%%%.")..'["\']%s*%)',code="--[[START OF MODULER: "..W.."]]\n"..a3:gsub("%%","%%%%").."\n"..B.."--[[END OF MODULER: "..W.."]]"})end;N=N:gsub('require%s*%(%s*["\']moduler["\']%s*%)','-- require("moduler") removed')for u,a4 in ipairs(U)do N=N:gsub(a4.marker,a4.code)end;local a5=b.."\\"..d.."_moduler.lua"local a6=io.open(a5,"wb")if not a6 then printErr("Error writing the built script: "..d)return false end;a6:write(N)a6:close()local a7,a8=loadstring(N,d..".lua")if not a7 then printErr(string.format('Syntax error in built script "%s": %s',d,a8))return false end;if extraFileWithNoModulerComments then local a9=b.."\\"..d.."_moduler_NoModulerComment.lua"local aa=io.open(a9,"wb")if not aa then printErr("Error writing the built script without moduler comments: "..d)return false end;local ab=N:gsub("\n[ \t]*%-%-%[%[START OF MODULER: [^%]%]]+%]%]\n","\n"):gsub("([ \t]*)%-%-%[%[START OF MODULER: [^%]%]]+%]%]\n","%1"):gsub("\n[ \t]*%-%-%[%[END OF MODULER: [^%]%]]+%]%]","")aa:write(ab)aa:close()end;local ac,ad=pcall(function()script.load(a5)end)if not ac then printErr("Error loading the built "..d..": "..ad)return false end;return true end;local ae=0;function _load(d)ae=ae+1;if ae>loadTryMax then return false end;local af=isScrLoaded(d)if af then local S=pcall(function()af:unload()end)if not S then printErr("Failed Unloading: "..d)return false end;local ag,ah=pcall(lua_thread.create,function()wait(100)_load(d)end)return false end;local J=getWorkingDirectory()local b=J.."/moduler"local K=b.."/"..d;if not doesDirectoryExist(b)then createDirectory(b)printErr('No Modules found for "'..d..'"')return false end;if not doesDirectoryExist(K)then printErr('No Modules found for "'..d..'"')return false end;return build(d)end;function load(d)ae=0;local d=d and noExt(d:trim())or nil;if not d or d==""or d:lower()=="moduler"then return false end;return _load(d)end;function main()if not isSampLoaded()or not isSampfuncsLoaded()then return end;while not isSampAvailable()do wait(0)end;sampRegisterChatCommand("moduler",function(d)local d=d and noExt(d:trim())or nil;if not d or d==""or d:lower()=="moduler"then return false end;load(d)end)while true do wait(0)end end;EXPORTS={load=load}
